BEGIN
  set_mode(m640x480);
  set_fps(60);
  screen_color(rgb(18, 28, 48));
  write(0, 320, 42, 1, "MUEVE TU NAVE CON LAS FLECHAS");
  nave_jugador();
  LOOP
